// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems, Neuron} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    Neuron neuron;

    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(
        address buyer,
        uint256 quantity,
        uint256 itemPrice,
        uint16 dailyAllowance
    ) public {
        vm.assume(buyer != address(0) && buyer.code.length == 0);
        vm.assume(buyer != address(this));
        dailyAllowance = uint16(bound(dailyAllowance, 1, 60000));
        quantity = bound(quantity, 1, dailyAllowance);
        itemPrice = bound(itemPrice, 1, 10 ** 20);

        neuron = new Neuron(address(this), address(this), address(this));
        c.instantiateNeuronContract(address(neuron));
        // c needs SPENDER_ROLE so it can approveSpender on behalf of the buyer
        neuron.addSpender(address(c));
        neuron.addMinter(address(this));

        // create a non-finite, transferable item with dailyAllowance units/day
        string[] memory noargs = new string[](0);
        noargs; // silence unused warnings style
        c.createGameItem(
            "item",
            "uri",
            false,
            true,
            0,
            itemPrice,
            dailyAllowance
        );

        // fund the buyer with exactly the purchase price
        neuron.mint(buyer, itemPrice * quantity);

        // daily window: replenishTime is 0 <= now, so the daily allowance applies
        vm.prank(buyer);
        c.mint(0, quantity);

        // GENERAL RULE: after a successful purchase of `quantity` within the
        // current daily window, remaining allowance must have decreased by
        // exactly `quantity` from the daily allowance.
        assertTrue(
            c.getAllowanceRemaining(buyer, 0) == uint256(dailyAllowance) - quantity,
            "allowance must decrease by purchased quantity"
        );
    }
}
